window.HARNESS_PY="# harness.py - runs one student snippet and returns its text output + any plots.\n# The SAME file is used inside the browser (Pyodide) and on the box (real Python) so outputs can be compared.\nimport sys, io, os, types, base64, linecache, traceback, warnings, contextlib\n\nDATA_DIR = os.getcwd()  # the folder that holds books_page1.html, the CSV files, etc.\n\n\ndef _install_requests_stand_in():\n    \"\"\"Browsers block live requests (CORS), so `requests.get` here returns a SAVED copy of books.toscrape.com.\"\"\"\n    class Response:  # only the three things the exam code uses: status_code, text, content\n        def __init__(self, status, text):\n            self.status_code = status\n            self.text = text\n            self.content = text.encode(\"utf-8\")\n\n    def get(url, *args, **kwargs):\n        if \"books.toscrape.com\" in str(url):  # only this practice site is saved offline\n            with open(os.path.join(DATA_DIR, \"books_page1.html\"), encoding=\"utf-8\") as f:\n                return Response(200, f.read())\n        return Response(404, \"Not available offline: only books.toscrape.com is saved on this site\")\n\n    mod = types.ModuleType(\"requests\")\n    mod.get = get\n    mod.__doc__ = \"offline stand-in for requests (practice site only)\"\n    sys.modules[\"requests\"] = mod\n\n\ndef run(code, name=\"<your code>\"):\n    \"\"\"Run `code` in a fresh namespace. Returns dict(out=str, error=str|None, images=[base64 png, ...]).\"\"\"\n    warnings.simplefilter(\"ignore\")  # keep the output clean: only what the student's code prints\n    _install_requests_stand_in()\n    out, images, error = io.StringIO(), [], None\n    plt = None\n    if \"matplotlib\" in code:  # only touch matplotlib when the snippet needs it\n        import matplotlib\n        matplotlib.use(\"Agg\")  # draw to memory (no window)\n        import matplotlib.pyplot as plt\n        plt.close(\"all\")\n\n        def _grab():  # turn every open figure into a PNG, then close it\n            for num in plt.get_fignums():\n                buf = io.BytesIO()\n                plt.figure(num).savefig(buf, format=\"png\", dpi=100, bbox_inches=\"tight\")\n                images.append(base64.b64encode(buf.getvalue()).decode())\n            plt.close(\"all\")\n\n        plt.show = lambda *a, **k: _grab()  # plt.show() now captures the plot instead of opening a window\n    linecache.cache[name] = (len(code), None, code.splitlines(True), name)  # lets tracebacks show your lines\n    ns = {\"__name__\": \"__main__\"}\n    with contextlib.redirect_stdout(out), contextlib.redirect_stderr(out):\n        try:\n            exec(compile(code, name, \"exec\"), ns)\n        except BaseException as e:  # noqa: BLE001 - show every error the way Python would\n            error = _format(e, name)\n    if plt is not None:\n        try:\n            _grab()  # a figure the code never showed\n        except Exception:\n            pass\n    return {\"out\": out.getvalue(), \"error\": error, \"images\": images}\n\n\ndef _format(e, name):\n    if isinstance(e, SyntaxError):  # compile-time errors have no useful traceback\n        return \"\".join(traceback.format_exception_only(type(e), e)).rstrip()\n    frames = [f for f in traceback.extract_tb(e.__traceback__) if f.filename == name]\n    lines = [\"Traceback (most recent call last):\"]\n    for f in frames:\n        lines.append(f'  File \"{name}\", line {f.lineno}, in {f.name}')\n        if f.line:\n            lines.append(\"    \" + f.line.strip())\n    lines.append(\"\".join(traceback.format_exception_only(type(e), e)).rstrip())\n    return \"\\n\".join(lines)\n";
